class UniqueResource {
    int* resource_;
public:
    UniqueResource() : resource_(new int(42)) {}
    ~UniqueResource() { delete resource_; } // Safe destruction (handles nullptr)

    // Move Constructor
    UniqueResource(UniqueResource&& other) noexcept
        : resource_(other.resource_)
    {
        // State Preservation: Moved-from object must be valid.
        // Set its internal resource pointer to null.
        other.resource_ = nullptr;
    }
    // other is now valid and harmlessly destructible.
};
